        auto key_of = [](const float T[3]) { return (uint64_t)(uint32_t)(int)(T[0] / 100.f) * 2654435761ull ^ (uint64_t)(uint32_t)(int)(T[1] / 100.f) * 40503ull ^ (uint64_t)(uint32_t)(int)(T[2] / 100.f) * 97ull; };
        static unsigned long long last_ride = 0;
