                        for (int q = 0; q < 3; q++) { g.R[0][q] = c * tp.R[0][q] + sn * tp.R[2][q]; g.R[1][q] = tp.R[1][q]; g.R[2][q] = -sn * tp.R[0][q] + c * tp.R[2][q];
                            g.S[q] = 1.f; g.T[q] = tp.T[q] + tp.R[2][q] * 1400.f; }
                        for (int e = 0; e < 16; e++) g.pal[e] = g.palw[e] = 0xFFFFFF;
