                            const float tt = now / 1000.f * (9.f + k) + (float)k, fl = 0.75f + 0.2f * sinf(tt) + 0.05f * sinf(tt * 3.1f);
                            float tpp[3]; for (int q = 0; q < 3; q++) tpp[q] = g.T[q] + tp.R[1][q] * y + (tp.R[0][q] * cosf(a) + tp.R[2][q] * sinf(a)) * 3000.f;
