                        VPIX_Instance g = {}; g.handle = 0x7FFF12F4u; g.light_mask = 1; g.bright = flash > 0.5f ? 1 : 0;
                        g.R[0][0] = fx[0]; g.R[0][1] = fx[1]; g.R[1][0] = -fx[1]; g.R[1][1] = fx[0]; g.R[2][2] = 1.f;
