                    if (pitch != 0.f) { const float c = cosf(pitch), sn = sinf(pitch); for (int q = 0; q < 3; q++) { const float a1 = g.R[1][q], a2 = g.R[2][q]; g.R[1][q] = c * a1 + sn * a2; g.R[2][q] = -sn * a1 + c * a2; } }
                    for (int q = 0; q < 3; q++) { g.S[q] = sc; g.T[q] = P[q] - g.R[2][q] * pm.zmin * sc; }
