                            pos = a + np - (room_b ? (std::min)(0.35f, (std::max)(0.f, np - m * step)) : 0.f) - (m - (r / 2) - 0.5f) * step + (room_bb ? 0.f : (r % 2) ? 0.25f : -0.25f) * step;
                            side = (r % 2) ? 1.f : -1.f;
