                            const float c2[4][3] = {{6000, 100, 5500}, {-6000, 100, 5500}, {-6000, 100, 8500}, {6000, 100, 8500}}; quadt(v, ps, c2, uv, TARCH, 0, 1, 0);
                            boxc(v, ps, -6300, -6000, -150, 150, -60, 8700, 0xDC3CFF); boxc(v, ps, 6000, 6300, -150, 150, -60, 8700, 0xDC3CFF);
